+    /**
+     * シェルの `${` の直後(`from`)から、対応する `}` の次の位置。`'…'` の外の `\` の次の字は飛ばす。`'…'` の中は次の `'` まで
+     * 字のまま(`\` も `${` も読まない)。`${` は `"…"` の中でも入れ子にし、`"` と `'` は `}` を待っている間だけ引用符として読む。
+     * @returns 対応する `}` の次の位置。行内で閉じなければ -1
+     */
+    const bracedVariableEndOf = (text, from) => {
+      // 待っている閉じ記号(`}` か `"`)を開いた順に並べた文字列。末尾が今の閉じ記号。
+      let closes = "}";
+      let at = from;
+      while (at < text.length) {
+        const char = text[at];
+        const close = closes[closes.length - 1];
+        if (char === "\\") {
+          at += 2;
+        } else if (char === close) {
+          closes = closes.slice(0, -1);
+          if (closes === "") return at + 1;
+          at += 1;
+        } else if (text.startsWith("${", at)) {
+          closes += "}";
+          at += 2;
+        } else if (close === "}" && char === '"') {
+          closes += '"';
+          at += 1;
+        } else if (close === "}" && char === "'") {
+          const quoteEnd = text.indexOf("'", at + 1);
+          if (quoteEnd < 0) return -1;
+          at = quoteEnd + 1;
+        } else {
+          at += 1;
+        }
+      }
+      return -1;
+    };
+
+    /**
